role="dialog" <button className="modal-close" onClick={onClose} aria-label={t("Fermer")}>×</button><div className="auth-brand"><span>M</span><div><strong>MATA</strong><small>BEAUTY</small></div></div><p className="eyebrow">{t("Compte sécurisé")}</p><label>{t("Langue préférée")}<select aria-label={t("Langue préférée")} value={locale.slice(0,2)} onChange={event => { const language = event.target.value; if(language === "fr" || language === "en" || language === "es") { setSelectedLocale(language); setValue("language", language); } }}>{SUPPORTED_LANGUAGES.map(language => <option key={language.code} value={language.code}>{language.label}</option>)}</select></label><h2 id="auth-title">{title}</h2><p className="auth-lead">{mode === "login" ? t("Retrouvez vos rendez-vous, favoris et recommandations personnalisées.") : mode === "register" ? t("Rejoignez l’expérience beauté premium pensée pour vous.") : mode === "confirm" ? t("Recevez un nouveau lien pour terminer votre inscription.") : mode === "email-link" ? t("Connectez-vous avec un lien envoyé à votre adresse e-mail.") : t("Nous vous aidons à retrouver rapidement votre espace.")}</p>{!configuration.configured && (
          <div className="configuration-warning" role="alert">
            {t("La connexion sécurisée est momentanément indisponible. Réessayez ultérieurement.")}</div>
        )}{(mode === "login" || mode === "register") && <>
          <button className="google-auth-button" type="button" onClick={() => void continueWithGoogle()} disabled={googleLoading || isSubmitting || phoneBusy || !configuration.configured}>
            <span aria-hidden="true">G</span>{googleLoading ? t("Ouverture de Google…") : t("Continuer avec Google")}
          </button>
          <div className="auth-divider"><span>{t("Adresse e-mail")}</span></div>
          {phoneAvailable && <div role="group" aria-label="Méthode de connexion"><button type="button" aria-pressed={method === "email"} disabled={phoneBusy || isSubmitting || googleLoading} onClick={() => setMethod("email")}>Email</button><button type="button" aria-pressed={method === "whatsapp"} disabled={phoneBusy || isSubmitting || googleLoading} onClick={() => setMethod("whatsapp")}>Téléphone (WhatsApp)</button></div>}
        </>}{phoneAvailable && method === "whatsapp" && (mode === "login" || mode === "register") ? <PhoneAuth key={mode} registering={mode === "register"} locale={locale} onVerified={completeAuthentication} onBusyChange={setPhoneBusy} /> : <form onSubmit={(event) => void handleSubmit(submit, () => setFeedback(""))(event)} noValidate>
          {mode === "register" && (
            <label>
              {t("Nom complet")}<input autoComplete="name" maxLength={80} aria-invalid={Boolean(errors.displayName)} aria-describedby={errors.displayName ? "auth-name-error" : undefined} {...register("displayName")} />
              {errors.displayName && <small id="auth-name-error" className="field-error" role="alert">{t(errors.displayName.message ?? "")}</small>}
            </label>
          )}
          {mode === "register" && <>
            <label>{t("Pays de résidence")}<select required aria-label={t("Pays de résidence")} {...register("countryCode")}><option value="">{t("Choisir un pays")}</option>{SUPPORTED_COUNTRIES.map(country => <option key={country.code} value={country.code}>{new Intl.DisplayNames([locale], { type: "region" }).of(country.code) ?? country.name}</option>)}</select></label>
            <label>{t("Région ou État")}<input autoComplete="address-level1" maxLength={120} {...register("region")} /></label>
            <label>{t("Ville")}<input autoComplete="address-level2" maxLength={120} {...register("city")} /></label>
            {phoneAvailable && <label>{t("Téléphone international")}<input type="tel" autoComplete="tel" placeholder="+221771234567" inputMode="tel" {...register("phone")} /></label>}
          </>}
          <label>
            {t("Adresse e-mail")}<input type="email" autoComplete="email" aria-invalid={Boolean(errors.email)} {...register("email")} />
            {errors.email && <small className="field-error">{t(errors.email.message ?? "")}</small>}
          </label>
          {(mode === "login" || mode === "register") && (
            <label>
              {t("Mot de passe")}<PasswordField locale={locale}
                autoComplete={mode === "register" ? "new-password" : "current-password"}
                aria-invalid={Boolean(errors.password)}
                {...register("password")}
              />
              {errors.password && <small className="field-error">{errors.password.message}</small>}
            </label>
          )}
          {mode === "register" && <>
            <label>{t("Confirmer le mot de passe")}<PasswordField locale={locale} autoComplete="new-password" {...register("confirmation")} /></label>
            <PasswordRequirements locale={locale} password={passwordValue} confirmation={confirmationValue} />
            <label className="legal-consent"><input type="checkbox" aria-label={t("Accepter les conditions générales et la politique de confidentialité")} {...register("acceptLegal")} /> <span>{t("J’accepte les")}{" "}<Link href="/legal/conditions-generales" target="_blank" rel="noopener noreferrer">{t("conditions générales")}</Link> {t("et la")}{" "}<Link href="/legal/confidentialite" target="_blank" rel="noopener noreferrer">{t("politique de confidentialité")}</Link> {t("de Mata Beauty.")}</span></label>
          </>}
          {feedback && <p className="auth-feedback" role="status">{t(feedback)}</p>}
          <button className="primary-button full" type="submit" disabled={isSubmitting || googleLoading || !configuration.configured}>
            {isSubmitting ? t("Veuillez patienter…") : mode === "login" ? t("Se connecter") : mode === "register" ? t("Créer le compte") : mode === "confirm" ? t("Renvoyer la confirmation") : t("Envoyer le lien")}
          </button>
        </form>}<div className="auth-links">
          {mode !== "login" && <button disabled={phoneBusy || isSubmitting || googleLoading} onClick={() => { setFeedback(""); setMode("login"); }}>{t("Déjà inscrit ? Se connecter")}</button>}
          {mode === "login" && <button disabled={phoneBusy || isSubmitting || googleLoading} onClick={() => { setFeedback(""); setMode("register"); }}>{t("Créer un compte")}</button>}
          {mode === "login" && <button disabled={phoneBusy || isSubmitting || googleLoading} onClick={() => { setFeedback(""); setMode("reset"); }}>{t("Mot de passe oublié")}</button>}
          {mode === "login" && <button disabled={phoneBusy || isSubmitting || googleLoading} onClick={() => { setFeedback(""); setMode("email-link"); }}>{t("Recevoir un lien de connexion")}</button>}
          {mode !== "confirm" && mode !== "register" && <button disabled={phoneBusy || isSubmitting || googleLoading} onClick={() => { setFeedback(""); setMode("confirm"); }}>{t("Renvoyer la confirmation")}</button>}
        </div>

événements:
onKeyDown={event => {
        if (event.key === "Escape") { event.preventDefault(); event.stopPropagation(); onClose(); return; }
        if (event.key !== "Tab") return;
        const items = Array.from(event.currentTarget.querySelectorAll<HTMLElement>("button:not(:disabled), a[href], input:not(:disabled):not([type=hidden]), select:not(:disabled), textarea:not(:disabled), [tabindex]"))
          .filter(element => element.tabIndex >= 0 && element.getClientRects().length > 0);
        const first = items[0], last = items.at(-1);
        if (!first) { event.preventDefault(); event.currentTarget.focus(); }
        else if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last?.focus(); }
        else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); }
      }}

