onMouseEnter={() => setInteracting(true)} onMouseLeave={() => setInteracting(false)} onFocus={() => setInteracting(true)} onBlur={() => setInteracting(false)} onClick={() => { if (suppressClick.current) { suppressClick.current = false; return; } onOpen(); }} onKeyDown={event => { if (event.key === "ArrowRight" || event.key === "ArrowLeft") { event.preventDefault(); advance(event.key === "ArrowRight" ? 1 : -1, true); } }} onPointerDown={event => { suppressClick.current = false; gesture.current = { x: event.clientX, y: event.clientY }; }} onPointerCancel={() => { gesture.current = null; }} onPointerUp={event => {
      const start = gesture.current; gesture.current = null; if (!start) return;
      const dx = event.clientX - start.x, dy = event.clientY - start.y;
      if (Math.abs(dx) > 35 && Math.abs(dx) > Math.abs(dy) * 1.4) {
        suppressClick.current = true; advance(dx < 0 ? 1 : -1, true);
      } else if (event.pointerType === "touch" && Math.abs(dx) < 10 && Math.abs(dy) < 10) {
        // Touch browsers need not synthesize a click after a carousel gesture.
        event.preventDefault(); suppressClick.current = true; onOpen();
      }
    }}

