aria-label="Importer une photo ou une vidéo" type="file" <header className="studio-hero"><div><span>STUDIO MATA BEAUTY</span><h2>Photo ou vidéo ?</h2><p>Choisissez votre média, préparez votre publication et partagez votre talent.</p></div><button type="button" onClick={() => picker.current?.click()}>＋ Créer</button></header><input ref={picker} hidden aria-label="Importer une photo ou une vidéo" type="file" accept={STUDIO_MEDIA_ACCEPT} multiple onChange={event => { const files = Array.from(event.target.files ?? []); if (!files.length) return; const error = mediaSelectionError(files); if (error) { setFeedback(error); event.target.value = ""; return; } setInitialFiles(files); setCreateType(isVideoFile(files[0]) ? "video" : "photo"); setSelectionVersion(value => value + 1); setActive("create"); setFeedback(""); event.target.value = ""; }} /><nav className="studio-tabs" aria-label="Navigation Studio">{tabs.map((tab) => <button className={active === tab.key ? "active" : ""} key={tab.key} onClick={() => setActive(tab.key)}>{tab.label}</button>)}</nav>{feedback && <p className="dashboard-feedback" role="status">{feedback}</p>}{firstPublicationFeedback && <aside className="panel studio-feedback"><strong>Le Studio était-il facile à utiliser ?</strong><div><button onClick={() => void answerStudioFeedback("yes")}>👍 Oui</button><button onClick={() => void answerStudioFeedback("no")}>👎 Non</button></div></aside>}{active === "create" && <VideoPublisher key={selectionVersion} initialFiles={initialFiles} userId={userId} providerApproved={providerApproved} initialContentType={createType} onPublished={async (postType) => {
      await load();
      setInitialFiles([]);
      setCreateType("video");
      setFirstPublicationFeedback(true);
      setActive(postType === "video" ? "videos" : postType === "before_after" ? "before_after" : "photos");
    }} />}{active === "statistics" && <SocialDashboard role="provider" userId={userId} />}{!(["create", "statistics"] as StudioTab[]).includes(active) && <article className="panel studio-library"><div className="panel-heading"><div><h2>{tabs.find((tab) => tab.key === active)?.label}</h2><p>Vos contenus, leurs statuts et leurs performances réelles.</p></div><button onClick={() => void load()}>Actualiser</button></div>
      {state === "loading" && <div className="compact-empty">Chargement de vos publications…</div>}
      {state === "error" && <div className="compact-empty">Vos publications sont momentanément indisponibles.</div>}
      {(state === "empty" || (state === "ready" && visible.length === 0)) && <div className="compact-empty">Publiez votre première réalisation.</div>}
      {visible.length > 0 && <div className="studio-post-grid">{visible.map((post) => <article key={post.id}>{post.thumbnail_url ? <Image src={post.thumbnail_url} alt="" width={320} height={420} unoptimized /> : <span className="studio-media-placeholder">▶</span>}<div><small>{statusLabel(post.post_type)} · {statusLabel(post.status)}</small><strong>{post.title || post.caption || "Publication Mata Beauty"}</strong><span>{post.view_count} vues · {post.like_count} likes · {post.comment_count} commentaires</span><time>{new Date(post.published_at ?? post.created_at).toLocaleDateString("fr-FR")}</time>{bookingAction(post)}<footer>{post.status === "published" && <button onClick={() => void manage(post.id, "hide")}>Masquer</button>}{["hidden", "archived"].includes(post.status) && <button onClick={() => void manage(post.id, "republish")}>Republier</button>}<button onClick={() => void manage(post.id, "archive")}>Archiver</button><button className="danger" onClick={() => void manage(post.id, "delete")}>Supprimer</button></footer></div></article>)}</div>}
    </article>}

