onPointerDown={event => { start.current = { x: event.clientX, y: event.clientY }; swiped.current = false; }} onPointerCancel={() => { start.current = null; }} onPointerUp={event => {
      if (start.current && start.current.x - event.clientX > 70 && start.current.x - event.clientX > Math.abs(start.current.y - event.clientY) * 1.5) { setActions(true); swiped.current = true; }
      start.current = null;
    }} onClick={() => { if (swiped.current) { swiped.current = false; return; } setOpen(value => !value); if (!open) onRead(); }}

nom_et_label_source:
aria-label={t("Vidéos beauté")} {feedTab === "following" && followingUnavailable && !collection ? <div className="social-feed-empty" role="alert"><h1>{t("Vos abonnements n’ont pas pu être chargés.")}</h1><button type="button" onClick={() => void load()}>{t("Réessayer")}</button></div> : visiblePosts.length === 0 && <div className="social-feed-empty following-empty"><span>♡</span><h1>{activeSearch ? t("Aucune vidéo pour ces filtres") : t(feedTab === "following" ? "Aucune vidéo de vos abonnements pour le moment." : "Les premières inspirations arrivent bientôt.")}</h1><p>{activeSearch ? t("Aucun contenu publié ne correspond à cette prestation, ce professionnel ou cette zone.") : t("Explorez les prestations et les professionnels près de vous.")}</p><button onClick={activeSearch ? clearSearch : openSearch}>{activeSearch ? t("Voir toutes les vidéos") : t("Rechercher une prestation")}</button></div>}{visiblePosts.map((post, index) => <article className="social-video-card" data-post-id={post.id} data-video-state={post.postType === "video" ? videoErrors.has(post.id) ? "error" : index === activeIndex && (videoLoading.has(post.id) || videoRefreshing.has(post.id)) ? "loading" : videoReady.has(post.id) ? "ready" : "waiting" : undefined} key={post.id} ref={(node) => { cards.current[index]=node; }} aria-label={`${t("Publication de")} ${post.businessName}`}>
      {post.postType === "video" ? (
        videoErrors.has(post.id) ? (
          <div className="video-fallback" role="alert">
            <span aria-hidden="true">◇</span>
            <p>{t("Cette vidéo ne peut pas être lue.")}</p>
            <button disabled={videoRefreshing.has(post.id)} onClick={() => void retryVideo(post)}>
              {t(videoRefreshing.has(post.id) ? "Rechargement…" : t("Réessayer"))}
            </button>
          </div>
        ) : !post.videoUrl ? (
          <div className="video-pending" aria-busy={videoRefreshing.has(post.id)}>
            {post.thumbnailUrl ? <Image className="video-poster-placeholder" src={post.thumbnailUrl} alt="" width={720} height={1280} unoptimized /> : <span aria-hidden="true">◇</span>}
            <p role="status">{t(videoRefreshing.has(post.id) ? "Chargement de la vidéo…" : "Vidéo en attente de chargement")}</p>
            <button disabled={videoRefreshing.has(post.id)} onClick={() => void retryVideo(post)}>
              {t(videoRefreshing.has(post.id) ? t("Chargement…") : t("Réessayer"))}
            </button>
          </div>
        ) : index !== activeIndex && index !== activeIndex + 1 ? (
          post.thumbnailUrl
            ? <Image className="video-poster-placeholder" src={post.thumbnailUrl} alt={t("Vidéo en attente de chargement")} width={720} height={1280} unoptimized />
            : <div className="video-poster-placeholder video-poster-placeholder-empty" role="img" aria-label={t("Vidéo en attente de chargement")}>◇</div>
        ) : (
          <video
            data-post-id={post.id}
            aria-label={t(videoReady.has(post.id) ? "Vidéo prête" : "Chargement de la vidéo")}
            ref={(node) => { videos.current[index] = node; }}
            src={post.videoUrl}
            poster={post.thumbnailUrl ?? undefined}
            muted={muted}
            loop
            playsInline
            preload={feedVideoPreload(index === activeIndex, saveData)}
            onLoadedMetadata={(event) => {
              const video = event.currentTarget;
              const position = playbackPositions.current.get(post.id) ?? 0;
              if (position > 0 && video.currentTime === 0) {
                try { video.currentTime = Number.isFinite(video.duration) && video.duration > 0 ? Math.min(position, Math.max(0, video.duration - 0.05)) : position; } catch { /* Playback remains usable for non-seekable media. */ }
              }
            }}
            onStalled={(event) => {
              if (index === activeIndex && event.currentTarget.readyState < 3 && !pausedPosts.has(post.id)) setVideoLoading(current => current.has(post.id) ? current : new Set(current).add(post.id));
            }}
            onLoadStart={() => {
              setVideoReady((current) => { const next = new Set(current); next.delete(post.id); return next; });
              setVideoLoading((current) => new Set(current).add(post.id));
            }}
            onWaiting={() => {
              setVideoReady((current) => { const next = new Set(current); next.delete(post.id); return next; });
              setVideoLoading((current) => current.has(post.id) ? current : new Set(current).add(post.id));
            }}
            onPlaying={() => {
              setVideoErrors((current) => { if (!current.has(post.id)) return current; const next = new Set(current); next.delete(post.id); return next; });
              autoRenewedVideos.current.delete(post.id);
              setVideoReady((current) => new Set(current).add(post.id));
              setVideoLoading((current) => { if (!current.has(post.id)) return current; const next = new Set(current); next.delete(post.id); return next; });
            }}
            onCanPlay={() => {
              setVideoReady((current) => new Set(current).add(post.id));
              setVideoLoading((current) => { const next = new Set(current); next.delete(post.id); return next; });
            }}
            onTimeUpdate={(event) => {
              const video = event.currentTarget;
              if (index !== activeIndex) return;
              playbackPositions.current.set(post.id, video.currentTime);
              const ratio = video.duration ? video.currentTime / video.duration : 0;
              setProgress((current) => Math.abs((current[post.id] ?? 0) - ratio) < 0.01 ? current : ({ ...current, [post.id]: ratio }));
              if (ratio >= 0.95 && !completedViews.current.has(post.id)) {
                completedViews.current.add(post.id);
                videoTopics(`${post.serviceTitle ?? ""} ${post.caption} ${post.hashtags.join(" ")}`).forEach(topic => interests.current.add(topic));
                const supabase = getSupabaseBrowserClient();
                if (supabase) void recordSessionMetric(supabase, "record_video_view", {
                  target_post_id: post.id,
                  target_watched_ms: Math.round(video.currentTime * 1000),
                  target_completed: true,
                }, "mata-feed-session", pageRequests.current.signal);
              }
            }}
            onError={() => handleVideoError(post)}
          />
        )
      ) : post.postType === "before_after" ? <div className="social-before-after"><figure><Image src={post.mediaUrls[0]} alt={t("Avant")} onError={() => { setUnavailablePosts((current) => new Set(current).add(post.id)); setActiveIndex(0); }} width={540} height={760} unoptimized /><figcaption>{t("Avant")}</figcaption></figure><figure><Image src={post.mediaUrls[1] ?? post.mediaUrls[0]} alt={t("Après")} onError={() => { setUnavailablePosts((current) => new Set(current).add(post.id)); setActiveIndex(0); }} width={540} height={760} unoptimized /><figcaption>{t("Après")}</figcaption></figure></div> : <Image className="social-photo-media" onError={() => { setUnavailablePosts((current) => new Set(current).add(post.id)); setActiveIndex(0); }} src={post.mediaUrls[0]} alt={post.title ?? post.caption} width={720} height={960} unoptimized />}
      {index === activeIndex && (videoLoading.has(post.id) || videoRefreshing.has(post.id)) && !videoErrors.has(post.id) && <span className="video-loading" role="status">{t("Chargement…")}</span>}
      <div className="video-shade" />
      <div className="video-progress" role="progressbar" aria-label={t("Progression de la vidéo")} aria-valuenow={Math.round((progress[post.id] ?? 0)*100)}><i style={{ transform: `scaleX(${progress[post.id] ?? 0})` }} /></div>
      {post.postType === "video" && !videoErrors.has(post.id) && <><button className="play-toggle" aria-label={t(pausedPosts.has(post.id) ? t("Lire la vidéo") : t("Mettre la vidéo en pause"))} onClick={() => { const next = new Set(pausedPosts); const video = videos.current[index]; if (next.has(post.id)) { next.delete(post.id); void video?.play().catch(() => undefined); } else { next.add(post.id); video?.pause(); } setPausedPosts(next); }}>{pausedPosts.has(post.id) && index===activeIndex ? "▶" : ""}</button><button className="sound-toggle" aria-label={t(muted ? t("Activer le son") : t("Couper le son"))} onClick={() => setMuted((value) => !value)}>{muted ? "♩×" : "♩"}</button></>}
      <aside className="social-actions" aria-label={t("Interactions de la publication")}>
        <button className="creator-orb" aria-label={`${t("Profil de")} ${post.businessName}`} onClick={() => void openProvider(post)}>{post.avatarUrl ? <Image src={post.avatarUrl} alt="" width={50} height={50} unoptimized /> : post.businessName.slice(0,2).toUpperCase()}</button>
        <button disabled={authPending || socialBusy.has(`like:${post.id}`)} aria-pressed={liked.has(post.id)} className={liked.has(post.id) ? "active" : ""} aria-label={t("J’aime")} onClick={() => void toggle("like",post)}>♥</button>
        <button disabled={authPending} aria-label={t("Commentaires")} onClick={() => void openComments(post)}>◌</button>
        <button disabled={authPending} aria-label={t("Partager")} onClick={() => void share(post)}>↗</button>
        <details className="feed-options"><summary aria-label={t("Plus d’options")}>•••</summary><div>
          <button type="button" onClick={() => openProvider(post)}>{t("Voir le profil")}</button>
          <button type="button" onClick={() => void shareProvider(post)}>{t("Partager le profil")}</button>
          <button disabled={authPending || socialBusy.has(`follow:${post.authorId}`)} aria-pressed={followed.has(post.authorId)} onClick={() => void follow(post)}>{t(followed.has(post.authorId) ? t("Se désabonner") : t("Suivre"))}</button>
          <button disabled={authPending || socialBusy.has(`save:${post.id}`)} aria-pressed={saved.has(post.id)} onClick={() => void toggle("save",post)}>{t(saved.has(post.id) ? t("Retirer des inspirations") : t("Enregistrer"))}</button>
          <button disabled={authPending} onClick={() => void report(post)}>{t("Signaler")}</button>
        </div></details>
      </aside>
      <div className="social-caption">
        <button className="creator-name" onClick={() => void openProvider(post)}>{post.businessName === t("Professionnel beauté") ? t(post.businessName) : post.businessName}</button>
        {post.city && <span className="feed-public-location">{post.city}</span>}
        {post.serviceId && post.serviceTitle && post.priceAmount !== null && post.durationMinutes !== null && <div className="linked-service">
          <button className="service-profile-link" onClick={() => void book(post)}><strong>{post.serviceTitle}</strong>{feedPrice(post.priceAmount, post.currency, locale) && <span>{feedPrice(post.priceAmount, post.currency, locale)}</span>}</button>
          <div className="feed-booking-actions"><button className="feed-availability" disabled={authPending} onClick={() => void book(post)}>{t("Voir les disponibilités")}</button><button className="feed-book" disabled={authPending} onClick={() => void book(post)}>{t("Réserver")}</button></div>
        </div>}
        {!post.serviceId && <div className="linked-service"><p>{t("Choisissez une prestation sur le profil du professionnel.")}</p><div className="feed-booking-actions"><button className="feed-book" onClick={() => book(post)}>{t("Réserver")}</button></div></div>}
      </div>
      <aside className="feed-premium-panel" aria-label={t("Informations de réservation")}>
        <div className="feed-premium-provider"><span>{t("Professionnel")}</span><button onClick={() => void openProvider(post)}>{post.businessName}</button>{post.verified && <span className="feed-verified">{t("Profil vérifié")}</span>}{post.city && <p>{post.city}</p>}</div>
        <div className="feed-premium-service"><span>{t("Prestation")}</span>{post.serviceId && post.serviceTitle ? <><h2>{post.serviceTitle}</h2><p>{post.priceAmount !== null && feedPrice(post.priceAmount, post.currency, locale) ? feedPrice(post.priceAmount, post.currency, locale) : t("Tarif non renseigné")}{post.durationMinutes !== null ? ` · ${post.durationMinutes} ${t("min")}` : ""}</p></> : <p>{t("Aucune prestation associée à cette publication.")}</p>}</div>
        <div className="feed-premium-availability"><span>{t("Disponibilités")}</span><p>{!post.serviceId ? t("Aucune prestation associée à cette publication.") : availabilityFailed.has(post.id) ? t("Disponibilités momentanément indisponibles.") : realAvailability[post.id] ? `${t("Prochain créneau")} · ${new Intl.DateTimeFormat(locale, { dateStyle: "medium", timeStyle: "short" }).format(new Date(realAvailability[post.id] as string))}` : availabilityChecked.has(post.id) ? t("Aucun créneau disponible dans les 14 prochains jours.") : t("Vérification des disponibilités…")}</p></div>
        <div className="feed-premium-actions">{post.serviceId && <button className="feed-premium-availability-button" disabled={authPending} onClick={() => void book(post)}>{t("Voir les disponibilités")}</button>}<button className="feed-premium-book" disabled={authPending} onClick={() => void book(post)}>{t("Réserver")}</button></div>
      </aside>
    </article>)}

événements:
onLoadedMetadata={(event) => {
              const video = event.currentTarget;
              const position = playbackPositions.current.get(post.id) ?? 0;
              if (position > 0 && video.currentTime === 0) {
                try { video.currentTime = Number.isFinite(video.duration) && video.duration > 0 ? Math.min(position, Math.max(0, video.duration - 0.05)) : position; } catch { /* Playback remains usable for non-seekable media. */ }
              }
            }} onStalled={(event) => {
              if (index === activeIndex && event.currentTarget.readyState < 3 && !pausedPosts.has(post.id)) setVideoLoading(current => current.has(post.id) ? current : new Set(current).add(post.id));
            }} onLoadStart={() => {
              setVideoReady((current) => { const next = new Set(current); next.delete(post.id); return next; });
              setVideoLoading((current) => new Set(current).add(post.id));
            }} onWaiting={() => {
              setVideoReady((current) => { const next = new Set(current); next.delete(post.id); return next; });
              setVideoLoading((current) => current.has(post.id) ? current : new Set(current).add(post.id));
            }} onPlaying={() => {
              setVideoErrors((current) => { if (!current.has(post.id)) return current; const next = new Set(current); next.delete(post.id); return next; });
              autoRenewedVideos.current.delete(post.id);
              setVideoReady((current) => new Set(current).add(post.id));
              setVideoLoading((current) => { if (!current.has(post.id)) return current; const next = new Set(current); next.delete(post.id); return next; });
            }} onCanPlay={() => {
              setVideoReady((current) => new Set(current).add(post.id));
              setVideoLoading((current) => { const next = new Set(current); next.delete(post.id); return next; });
            }} onTimeUpdate={(event) => {
              const video = event.currentTarget;
              if (index !== activeIndex) return;
              playbackPositions.current.set(post.id, video.currentTime);
              const ratio = video.duration ? video.currentTime / video.duration : 0;
              setProgress((current) => Math.abs((current[post.id] ?? 0) - ratio) < 0.01 ? current : ({ ...current, [post.id]: ratio }));
              if (ratio >= 0.95 && !completedViews.current.has(post.id)) {
                completedViews.current.add(post.id);
                videoTopics(`${post.serviceTitle ?? ""} ${post.caption} ${post.hashtags.join(" ")}`).forEach(topic => interests.current.add(topic));
                const supabase = getSupabaseBrowserClient();
                if (supabase) void recordSessionMetric(supabase, "record_video_view", {
                  target_post_id: post.id,
                  target_watched_ms: Math.round(video.currentTime * 1000),
                  target_completed: true,
                }, "mata-feed-session", pageRequests.current.signal);
              }
            }} onError={() => handleVideoError(post)}

onCancel={event => { event.preventDefault(); if (!busy) onCancel(); }} onKeyDown={event => {
    if (event.key !== "Tab") return;
    const controls = Array.from(event.currentTarget.querySelectorAll<HTMLElement>('button:not([disabled]),textarea:not([disabled]),input:not([disabled]),select:not([disabled]),a[href]'));
    const first = controls[0], last = controls.at(-1);
    if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last?.focus(); }
    else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first?.focus(); }
  }}

onClick={() => {
              setCollapsed(false);
              setExpandedGroup(isOpen ? "" : group.key);
              try { window.localStorage.setItem("mata-admin-open-group", isOpen ? "" : group.key); } catch { /* Storage is optional. */ }
            }}

onClick={() => {
              const target: ModuleKey = result.entity_type === "user" ? "users" : result.entity_type === "provider" ? "providers" : result.entity_type === "booking" ? "bookings" : result.entity_type === "payment" ? "payments" : result.entity_type === "ticket" ? "support" : "promotions";
              navigateToModule(target);
              setSearchResults([]);
              setGlobalQuery("");
            }}

onCancel={() => setConfirmation(null)} onConfirm={async (reason) => {
      const { error } = await getSupabaseBrowserClient()!.rpc("admin_set_user_suspension", { target_user_id: confirmation.user_id, suspended: !confirmation.is_suspended, reason });
      if (error) notify(publicErrorMessage(error, "Le compte n’a pas pu être mis à jour.")); else notify("Compte mis à jour et action journalisée.");
      setConfirmation(null);
      await load();
    }}

onCancel={() => setConfirmation(null)} onConfirm={async (reason) => {
      const { error } = await getSupabaseBrowserClient()!.rpc("admin_set_provider_status", { target_provider_id: confirmation.row.profile_id, next_status: confirmation.status, reason });
      notify(error ? publicErrorMessage(error, "La décision n’a pas pu être appliquée.") : "Décision appliquée et journalisée.");
      setConfirmation(null);
      await load();
    }}

onCancel={() => setConfirmation(null)} onConfirm={async (reason) => {
    const { error } = await getSupabaseBrowserClient()!.rpc("admin_update_booking_status", { target_booking_id: confirmation.id, next_status: "cancelled_by_provider", reason });
    notify(error ? publicErrorMessage(error, "La réservation n’a pas pu être mise à jour.") : "Réservation mise à jour et auditée.");
    setRows((current) => current.map((row) => row.id === confirmation.id ? { ...row, status: "cancelled_by_provider" } : row));
    setConfirmation(null);
  }}

onCancel={() => setConfirmation(null)} onConfirm={async (reason) => {
        const supabase = getSupabaseBrowserClient()!;
        const result = confirmation.action === "feature"
          ? await supabase.rpc("admin_feature_social_post", { target_post_id: confirmation.row.id, target_feature_type: "recommended", target_starts_at: new Date().toISOString(), target_ends_at: new Date(Date.now() + 7 * 86400000).toISOString(), target_position: null, target_audience: { type: "all" }, target_geographic_zone: null, reason })
          : await supabase.rpc("admin_moderate_social_post", { target_post_id: confirmation.row.id, decision: confirmation.action, reason });
        notify(result.error ? publicErrorMessage(result.error, "La décision de modération n’a pas pu être appliquée.") : confirmation.action === "feature" ? "Publication mise en avant pendant 7 jours." : "Décision appliquée et auditée.");
        setConfirmation(null);
        if (!result.error) await load();
      }}

onCancel={() => setConfirmation(false)} onConfirm={async (reason) => {
    const next = { enabled: !enabled, message, allow_admins: true, allow_clients: false, allow_providers: false };
    const { error } = await getSupabaseBrowserClient()!.rpc("admin_update_setting", { setting_key: "maintenance", setting_value: next, reason });
    notify(error ? publicErrorMessage(error, "Le mode maintenance n’a pas pu être modifié.") : `Mode maintenance ${!enabled ? "activé" : "désactivé"}.`);
    if (!error) setEnabled(!enabled);
    setConfirmation(false);
  }}

onDismiss={() => setAccessToRevoke(null)} onConfirm={async () => {
        const success = await mutate(async () => { await requestTeamApi(businessId, "POST", { action: "revoke_access", businessId, collaboratorId: accessToRevoke.collaborator_id }); }, "Accès révoqué immédiatement. Les fiches et l’historique sont conservés.");
        if (success) setAccessToRevoke(null);
        return success;
      }}

nom_et_label_source:
type="hidden" name="contentType" <input type="hidden" name="contentType" value={contentType} /><div className="wide composer-media">
        <input ref={mediaInput} aria-label="Choisir une photo ou une vidéo" type="file" accept={STUDIO_MEDIA_ACCEPT} disabled={phase !== "idle"} multiple onChange={event => {
          const files = Array.from(event.target.files ?? []); if (!files.length) return;
          const error = mediaSelectionError(files); if (error) { setFeedback(error); event.target.value = ""; return; }
          setSelectedFiles(files); setPreviewUrls(files.map(file => URL.createObjectURL(file))); setCropping(null); setFeedback("");
          setContentType(isVideoFile(files[0]) ? "video" : ["before_after", "promotion", "availability"].includes(contentType) ? contentType : "photo");
        }} />
        {previewUrls.length === 0 ? <p>Formats de téléphone et autres formats vidéo : conversion automatique si nécessaire. Choisissez une vidéo sans limite de durée (100 Mo maximum par fichier) ou jusqu’à 10 photos.</p> : <div className="composer-previews">{previewUrls.map((url, index) => <div key={url}>{contentType === "video" ? <>{videoPreview.url ? <video src={videoPreview.url} controls playsInline preload="auto" poster={videoPreview.poster} aria-label="Aperçu de votre vidéo" onError={videoPreview.fail} /> : <p>{videoPreview.busy ? "Préparation de l’aperçu vidéo…" : "Aperçu indisponible. Votre sélection est conservée."}</p>}</> : <><Image src={url} alt={`Photo ${index + 1}`} width={500} height={650} unoptimized /><button type="button" onClick={() => setCropping(index)}>Recadrer la photo {index + 1}</button></>}</div>)}</div>}
        {cropping !== null && selectedFiles[cropping] && <PhotoCropper key={previewUrls[cropping]} file={selectedFiles[cropping]} onCancel={() => setCropping(null)} onApply={file => {
          if (file.size > MAX_IMAGE_BYTES) { setFeedback("Le recadrage dépasse 12 Mo. Choisissez un cadrage plus petit."); setCropping(null); return; }
          const files = selectedFiles.map((old, index) => index === cropping ? file : old);
          setSelectedFiles(files); setPreviewUrls(files.map(item => URL.createObjectURL(item))); setCropping(null); setFeedback("");
        }} />}
        {selectedFiles.length > 0 && contentType !== "video" && <details><summary>Autres formats photo</summary><label>Format<select value={contentType} onChange={event => setContentType(event.target.value as ContentType)}><option value="photo">Photo / carrousel</option><option value="before_after">Avant / Après (2 photos)</option><option value="promotion">Promotion</option><option value="availability">Disponibilité immédiate</option></select></label></details>}
        <div className="composer-actions"><button type="button" disabled={phase !== "idle"} onClick={() => mediaInput.current?.click()}>{selectedFiles.length ? "Changer les médias" : "＋ Choisir une photo ou une vidéo"}</button></div>
      </div><fieldset className="wide composer-details" disabled={phase !== "idle"}>
      <h3>Votre publication</h3>
      <label>Titre<input name="title" maxLength={120} placeholder="Ajoutez un titre" /></label>
      <label className="wide">Légende<textarea name="caption" maxLength={2200} rows={3} placeholder="Expliquez la technique, le résultat ou le conseil beauté…" /></label>
      <label className="wide">Hashtags<input name="hashtags" maxLength={300} placeholder="#tresses #dakar #soins" /></label>
      <details className="wide publisher-options"><summary>Localisation</summary><label>Localisation<input name="location" maxLength={160} placeholder="Dakar, Sénégal" /></label></details>
      {contentType === "availability" && <label>Créneau disponible<input name="availableAt" type="datetime-local" required /></label>}
      {contentType === "promotion" && <><label>Remise (%)<input name="discount" type="number" min="1" max="90" required /></label><label>Fin de l’offre<input name="promotionEndsAt" type="datetime-local" required /></label><label>Places disponibles<input name="promotionSlots" type="number" min="1" max="10000" required /></label></>}
      {servicesError && <p role="alert">{servicesError}</p>}
      <p className="wide"><Link href="/salon/services">Gérer les prestations dans l’espace Salon</Link></p>
      <label>Catégorie et prestation<select name="serviceId" value={serviceId} onChange={event => setServiceId(event.target.value)}><option value="">Choisir une prestation</option>{services.map((service) => <option key={service.id} value={service.id}>{service.services?.categories?.name ?? "Beauté"} · {service.title}{!studioServiceIsPublic(service) ? " (non publiée · brouillon uniquement)" : ""} · {service.duration_minutes} min · {formatServiceMoney(service.price_amount, service.currency)}</option>)}</select></label>
      <details className="wide publisher-options"><summary>Options de publication</summary>
      <label>Visibilité<select name="visibility" defaultValue="public"><option value="public">Tout le monde</option><option value="followers">Abonnés</option></select></label>
      {contentType === "video" && <label>Couverture personnalisée<input name="thumbnail" type="file" accept="image/jpeg,image/png,image/webp" /></label>}<label>Publication<select name="status" defaultValue={providerApproved ? "published" : "draft"}><option value="draft">Brouillon</option><option value="scheduled" disabled={!providerApproved}>Programmer</option><option value="published" disabled={!providerApproved}>Publier maintenant</option></select></label>
      <label>Date programmée<input name="scheduledFor" type="datetime-local" /></label>
      <label className="wide legal-consent"><input name="allowComments" type="checkbox" defaultChecked /><span>Autoriser les commentaires.</span></label>
      </details>
      <label className="wide legal-consent"><input name="consent" type="checkbox" /><span>Je confirme avoir l’autorisation des personnes reconnaissables dans ce contenu.</span></label>
      {!providerApproved && <p className="wide publisher-notice">Votre profil doit être approuvé avant une publication publique. Le brouillon reste disponible.</p>}

      {!feedback && videoPreview.message && <p className="wide dashboard-feedback" role="status">{videoPreview.message}</p>}
      {contentType === "video" && selectedFiles.length > 0 && !videoPreview.busy && !videoPreview.file && <button type="button" onClick={videoPreview.retry}>Réessayer la préparation de l’aperçu</button>}
      {phase !== "idle" && <label className="wide upload-progress">Progression de la publication<progress max="100" value={progressValue} /><span>{progressValue}% · {busyLabel}</span></label>}
      <button className="primary-button" type="submit" disabled={phase !== "idle" || videoPreview.busy || (contentType === "video" && !videoPreview.file) || !selectedFiles.length || cropping !== null || publicationUnconfirmed}>{busyLabel}</button>
      </fieldset>{publicationUnconfirmed && <button type="button" onClick={() => window.location.reload()}>Actualiser le Studio</button>}{feedback && <p className="wide dashboard-feedback" role="status">{feedback}</p>}

